def solve(y,s):
    pos=[s[i] for i,v in enumerate(y) if v]
    neg=[s[i] for i,v in enumerate(y) if not v]
    if not pos or not neg: return None
    return sum(1 if a>b else 0.5 if a==b else 0 for a in pos for b in neg)/(len(pos)*len(neg))
